CREATE TABLE `accidents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `bicycleId` bigint(20) unsigned NOT NULL,
  `rentalId` bigint(20) unsigned DEFAULT NULL,
  `riderId` bigint(20) unsigned DEFAULT NULL,
  `riderName` varchar(255) DEFAULT NULL,
  `type` enum('accident','geofence_breach','geofence_alert','impact_detected','theft') NOT NULL DEFAULT 'accident',
  `severity` varchar(32) NOT NULL DEFAULT 'minor',
  `description` text DEFAULT NULL,
  `gpsLocation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gpsLocation`)),
  `accelerometerData` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`accelerometerData`)),
  `impactForce` decimal(10,2) DEFAULT NULL,
  `imageUrl` varchar(255) DEFAULT NULL,
  `acknowledged` tinyint(1) NOT NULL DEFAULT 0,
  `acknowledgedBy` bigint(20) unsigned DEFAULT NULL,
  `acknowledgedAt` timestamp NULL DEFAULT NULL,
  `alertSent` tinyint(1) NOT NULL DEFAULT 0,
  `reportedBy` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'open',
  `investigationStatus` varchar(255) NOT NULL DEFAULT 'pending',
  `breachDistance` decimal(10,2) DEFAULT NULL,
  `breachDirection` varchar(255) DEFAULT NULL,
  `actionTaken` text DEFAULT NULL,
  `resolutionNotes` text DEFAULT NULL,
  `resolvedBy` bigint(20) unsigned DEFAULT NULL,
  `resolvedAt` timestamp NULL DEFAULT NULL,
  `lastEscalatedAt` timestamp NULL DEFAULT NULL,
  `warningLevel` varchar(255) DEFAULT NULL,
  `distanceFromBoundary` decimal(10,2) DEFAULT NULL,
  `location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`location`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `accidents_bicycleid_index` (`bicycleId`),
  KEY `accidents_type_index` (`type`),
  KEY `accidents_severity_index` (`severity`),
  KEY `accidents_status_index` (`status`),
  KEY `accidents_acknowledged_index` (`acknowledged`),
  KEY `accidents_created_at_index` (`created_at`),
  KEY `accidents_rentalid_foreign` (`rentalId`),
  KEY `accidents_riderid_foreign` (`riderId`),
  KEY `accidents_investigationstatus_index` (`investigationStatus`),
  KEY `accidents_resolvedby_foreign` (`resolvedBy`),
  KEY `accidents_acknowledgedby_foreign` (`acknowledgedBy`),
  CONSTRAINT `accidents_acknowledgedby_foreign` FOREIGN KEY (`acknowledgedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `accidents_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `accidents_rentalid_foreign` FOREIGN KEY (`rentalId`) REFERENCES `rentals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `accidents_resolvedby_foreign` FOREIGN KEY (`resolvedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `accidents_riderid_foreign` FOREIGN KEY (`riderId`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
