--
-- Table structure for table `bicycles`
--

DROP TABLE IF EXISTS `bicycles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bicycles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `model` varchar(255) DEFAULT NULL,
  `serialNumber` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `status` enum('available','rented','maintenance','out_of_service','removed') NOT NULL DEFAULT 'available',
  `hourlyRate` decimal(8,2) NOT NULL,
  `currentLat` decimal(10,7) DEFAULT NULL,
  `currentLng` decimal(10,7) DEFAULT NULL,
  `batteryLevel` int(11) NOT NULL DEFAULT 100,
  `lockStatus` enum('locked','unlocked') NOT NULL DEFAULT 'locked',
  `iotEnabled` tinyint(1) NOT NULL DEFAULT 0,
  `qrCode` varchar(255) DEFAULT NULL,
  `deviceApiKey` varchar(64) DEFAULT NULL,
  `deviceKeyProvisionedAt` timestamp NULL DEFAULT NULL,
  `totalRentals` int(11) NOT NULL DEFAULT 0,
  `totalDistance` decimal(10,2) NOT NULL DEFAULT 0.00,
  `condition` enum('good','needs_inspection','damaged','fair','needs_maintenance') NOT NULL DEFAULT 'good',
  `lastMaintenanceDate` timestamp NULL DEFAULT NULL,
  `currentRider` bigint(20) unsigned DEFAULT NULL,
  `currentRentalId` varchar(255) DEFAULT NULL,
  `lastGpsUpdate` timestamp NULL DEFAULT NULL,
  `lastHeartbeat` timestamp NULL DEFAULT NULL,
  `lastLockAction` timestamp NULL DEFAULT NULL,
  `lockActionBy` varchar(255) DEFAULT NULL,
  `addedBy` bigint(20) unsigned DEFAULT NULL,
  `removedAt` timestamp NULL DEFAULT NULL,
  `removedBy` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bicycles_serialnumber_unique` (`serialNumber`),
  UNIQUE KEY `bicycles_qrcode_unique` (`qrCode`),
  UNIQUE KEY `bicycles_deviceapikey_unique` (`deviceApiKey`),
  KEY `bicycles_addedby_foreign` (`addedBy`),
  KEY `bicycles_removedby_foreign` (`removedBy`),
  KEY `bicycles_status_index` (`status`),
  KEY `bicycles_lockstatus_index` (`lockStatus`),
  KEY `bicycles_condition_index` (`condition`),
  KEY `bicycles_currentrider_index` (`currentRider`),
  KEY `currentLng` (`currentLat`),
  KEY `bicycles_iotenabled_index` (`iotEnabled`),
  CONSTRAINT `bicycles_addedby_foreign` FOREIGN KEY (`addedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `bicycles_currentrider_foreign` FOREIGN KEY (`currentRider`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `bicycles_removedby_foreign` FOREIGN KEY (`removedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

