CREATE TABLE `device_commands` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `bicycleId` bigint(20) unsigned NOT NULL,
  `command` varchar(255) NOT NULL COMMENT 'lock, unlock, restart, calibrate, disable, enable',
  `params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`params`)),
  `status` varchar(255) NOT NULL DEFAULT 'pending' COMMENT 'pending, sent, executed, failed',
  `issuedBy` bigint(20) unsigned DEFAULT NULL,
  `executedAt` timestamp NULL DEFAULT NULL,
  `response` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `device_commands_issuedby_foreign` (`issuedBy`),
  KEY `device_commands_bicycleid_index` (`bicycleId`),
  KEY `device_commands_status_index` (`status`),
  CONSTRAINT `device_commands_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `device_commands_issuedby_foreign` FOREIGN KEY (`issuedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
