--
-- Table structure for table `device_status`
--

DROP TABLE IF EXISTS `device_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `device_status` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `bicycleId` bigint(20) unsigned NOT NULL,
  `gps` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gps`)),
  `accelerometer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`accelerometer`)),
  `battery` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`battery`)),
  `lockStatus` varchar(255) DEFAULT NULL,
  `lcdTimer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`lcdTimer`)),
  `deviceVersion` varchar(255) DEFAULT NULL,
  `uptime` int(11) DEFAULT NULL,
  `command` varchar(255) DEFAULT NULL,
  `commandIssuedBy` bigint(20) unsigned DEFAULT NULL,
  `commandIssuedAt` timestamp NULL DEFAULT NULL,
  `type` enum('heartbeat','command','lock_command') NOT NULL DEFAULT 'heartbeat',
  `eventTimestamp` timestamp NULL DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`params`)),
  `issuedByName` varchar(255) DEFAULT NULL,
  `sentAt` timestamp NULL DEFAULT NULL,
  `acknowledgedAt` timestamp NULL DEFAULT NULL,
  `completedAt` timestamp NULL DEFAULT NULL,
  `result` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `device_status_commandissuedby_foreign` (`commandIssuedBy`),
  KEY `device_status_bicycleid_index` (`bicycleId`),
  KEY `device_status_type_index` (`type`),
  KEY `device_status_eventtimestamp_index` (`eventTimestamp`),
  KEY `device_status_bicycleid_eventtimestamp_index` (`bicycleId`,`eventTimestamp`),
  KEY `device_status_command_index` (`command`),
  CONSTRAINT `device_status_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `device_status_commandissuedby_foreign` FOREIGN KEY (`commandIssuedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2734 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

