--
-- Table structure for table `geofence_breaches`
--

DROP TABLE IF EXISTS `geofence_breaches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `geofence_breaches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `bicycleId` bigint(20) unsigned NOT NULL,
  `geofenceId` bigint(20) unsigned DEFAULT NULL,
  `lat` decimal(10,7) NOT NULL,
  `lng` decimal(10,7) NOT NULL,
  `distance` decimal(10,2) NOT NULL COMMENT 'Distance from geofence center in meters',
  `acknowledged` tinyint(1) NOT NULL DEFAULT 0,
  `resolvedAt` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `geofence_breaches_geofenceid_foreign` (`geofenceId`),
  KEY `geofence_breaches_bicycleid_index` (`bicycleId`),
  KEY `geofence_breaches_acknowledged_index` (`acknowledged`),
  CONSTRAINT `geofence_breaches_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `geofence_breaches_geofenceid_foreign` FOREIGN KEY (`geofenceId`) REFERENCES `geofences` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

