--
-- Table structure for table `geofences`
--

DROP TABLE IF EXISTS `geofences`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `geofences` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT 'Default Geofence',
  `centerLat` decimal(10,7) NOT NULL,
  `centerLng` decimal(10,7) NOT NULL,
  `radius` decimal(10,2) NOT NULL COMMENT 'Radius in meters',
  `shapeType` varchar(255) NOT NULL DEFAULT 'circle' COMMENT 'circle, oval_h, oval_v, rectangle, polygon',
  `width` decimal(10,2) DEFAULT NULL COMMENT 'Meters (oval width / rectangle width)',
  `height` decimal(10,2) DEFAULT NULL COMMENT 'Meters (oval height / rectangle height)',
  `rotation` decimal(10,2) DEFAULT NULL COMMENT 'Degrees clockwise from north (rectangle)',
  `points` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Polygon vertices [{lat,lng}] when shapeType=polygon' CHECK (json_valid(`points`)),
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `alertEnabled` tinyint(1) NOT NULL DEFAULT 1,
  `warningThreshold` decimal(10,2) DEFAULT NULL COMMENT 'Distance in meters from boundary that triggers a warning',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `geofences_isactive_index` (`isActive`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

