  `bicycleId` bigint(20) unsigned NOT NULL,
  `lat` decimal(10,7) NOT NULL,
  `lng` decimal(10,7) NOT NULL,
  `speed` decimal(8,2) DEFAULT NULL,
  `heading` decimal(6,2) DEFAULT NULL,
  `accuracy` decimal(8,2) DEFAULT NULL,
  `batteryLevel` int(11) DEFAULT NULL,
  `altitude` decimal(8,2) DEFAULT NULL,
  `satellites` int(11) DEFAULT NULL,
  `hdop` decimal(6,2) DEFAULT NULL,
  `timestamp` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `source` varchar(255) NOT NULL DEFAULT 'gps',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `gps_logs_bicycleid_index` (`bicycleId`),
  KEY `gps_logs_timestamp_index` (`timestamp`),
  KEY `gps_logs_bicycleid_timestamp_index` (`bicycleId`,`timestamp`),
  CONSTRAINT `gps_logs_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1525 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
