  KEY `payments_bicycleid_foreign` (`bicycleId`),
  KEY `payments_userid_status_index` (`userId`,`status`),
  KEY `payments_rentalid_index` (`rentalId`),
  KEY `payments_paymongopaymentid_index` (`paymongoPaymentId`),
  KEY `payments_status_created_at_index` (`status`,`created_at`),
  CONSTRAINT `payments_bicycleid_foreign` FOREIGN KEY (`bicycleId`) REFERENCES `bicycles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_rentalid_foreign` FOREIGN KEY (`rentalId`) REFERENCES `rentals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_userid_foreign` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
