DROP TABLE IF EXISTS `refunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `refunds` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `paymentId` bigint(20) unsigned NOT NULL,
  `userId` bigint(20) unsigned NOT NULL,
  `refundReference` varchar(255) NOT NULL,
  `paymongoRefundId` varchar(255) DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'PHP',
  `reason` enum('customer_request','duplicate_payment','fraudulent','service_not_provided','other') NOT NULL DEFAULT 'customer_request',
  `reasonDetails` text DEFAULT NULL,
  `status` enum('pending','processing','succeeded','failed','cancelled') NOT NULL DEFAULT 'pending',
  `paymongoResponse` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`paymongoResponse`)),
  `processedAt` timestamp NULL DEFAULT NULL,
  `failureReason` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `refunds_refundreference_unique` (`refundReference`),
  UNIQUE KEY `refunds_paymongorefundid_unique` (`paymongoRefundId`),
  KEY `refunds_userid_foreign` (`userId`),
  KEY `refunds_paymentid_index` (`paymentId`),
  KEY `refunds_status_created_at_index` (`status`,`created_at`),
  CONSTRAINT `refunds_paymentid_foreign` FOREIGN KEY (`paymentId`) REFERENCES `payments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `refunds_userid_foreign` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
