  `finalFee` decimal(10,2) DEFAULT NULL,
  `warningSentAt` timestamp NULL DEFAULT NULL,
  `expiredAt` timestamp NULL DEFAULT NULL,
  `returnDeadline` timestamp NULL DEFAULT NULL,
  `returnDeadlineSetBy` varchar(255) DEFAULT NULL,
  `penaltyType` varchar(255) DEFAULT NULL,
  `penaltyValue` decimal(10,2) DEFAULT NULL,
  `penaltyAccrued` decimal(10,2) DEFAULT NULL,
  `overdueReturnAt` timestamp NULL DEFAULT NULL,
  `paymentMethod` varchar(255) DEFAULT NULL,
  `paymentReference` varchar(255) DEFAULT NULL,
  `prePaidAmount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `balanceDue` decimal(12,2) DEFAULT NULL,
