DROP TABLE IF EXISTS `reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reportId` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  `format` varchar(255) NOT NULL DEFAULT 'pdf',
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `filters` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`filters`)),
  `summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`summary`)),
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `generatedAt` timestamp NULL DEFAULT NULL,
  `generatedBy` bigint(20) unsigned DEFAULT NULL,
  `downloadUrl` varchar(255) DEFAULT NULL,
  `fileName` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reports_reportid_unique` (`reportId`),
  KEY `reports_type_index` (`type`),
  KEY `reports_status_index` (`status`),
  KEY `reports_generatedby_index` (`generatedBy`),
  KEY `reports_generatedat_index` (`generatedAt`),
  CONSTRAINT `reports_generatedby_foreign` FOREIGN KEY (`generatedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

